201	+import type { CapturedLayer } from '@wolsok/feat-bacteria-rendering';
202	+
203	+/** How long a saved sheet's address stays valid for the download. */
204	+const REVOKE_AFTER_MS = 60_000;
205	+
206	+/** The height of the row with a layer's name above it, in pixels. */
207	+export const LABEL_HEIGHT = 18;
208	+
209	+/** Where a layer goes on the sheet. */
210	+export interface SheetPlacement {
211	+  label: string;
212	+  /** The top of its label row. */
213	+  labelY: number;
214	+  /** The top of its pictures, under the label. */
215	+  imageY: number;
216	+  /** The left of its alpha picture, right of its colours. */
217	+  alphaX: number;
218	+}
219	+
220	+/**
221	+ * The GL diagnostic's sheet: the layers one under the other, each under a
222	+ * row with its name, its colours on the left and its alpha beside them -
223	+ * the glow packs colony ids into its alpha, so that is half of what to see.
224	+ */
225	+export function sheetLayout(
226	+  layers: readonly Pick<CapturedLayer, 'label' | 'width' | 'height'>[]
227	+): { width: number; height: number; placements: SheetPlacement[] } {
228	+  let top = 0;
229	+  const placements = layers.map(({ label, width, height }) => {
230	+    const placement = {
231	+      label,
232	+      labelY: top,
233	+      imageY: top + LABEL_HEIGHT,
234	+      alphaX: width,
235	+    };
236	+    top += LABEL_HEIGHT + height;
237	+    return placement;
238	+  });
239	+  return {
240	+    width: Math.max(0, ...layers.map((layer) => layer.width * 2)),
241	+    height: top,
242	+    placements,
243	+  };
244	+}
245	+
246	+/** A layer's RGBA as its colours, opaque, and its alpha as grey. */
247	+export function splitAlpha(pixels: Uint8Array): {
248	+  colors: Uint8ClampedArray<ArrayBuffer>;
249	+  alpha: Uint8ClampedArray<ArrayBuffer>;
250	+} {
251	+  const colors = new Uint8ClampedArray(pixels);
252	+  const alpha = new Uint8ClampedArray(pixels.length);
253	+  for (let i = 0; i < pixels.length; i += 4) {
254	+    colors[i + 3] = 255;
255	+    alpha.fill(pixels[i + 3], i, i + 3);
256	+    alpha[i + 3] = 255;
257	+  }
258	+  return { colors, alpha };
259	+}
260	+
261	+/** Draws the sheet of the layers - null where the canvas gives no 2D context. */
262	+function drawSheet(layers: readonly CapturedLayer[]): HTMLCanvasElement | null {
263	+  const { width, height, placements } = sheetLayout(layers);
264	+  const canvas = document.createElement('canvas');
265	+  canvas.width = width;
266	+  canvas.height = height;
267	+  const cx = canvas.getContext('2d');
268	+  if (cx == null) {
269	+    return null;
270	+  }
271	+  cx.fillStyle = '#000';
272	+  cx.fillRect(0, 0, width, height);
273	+  cx.font = `${LABEL_HEIGHT - 4}px monospace`;
274	+  cx.textBaseline = 'top';
275	+  layers.forEach((layer, index) => {
276	+    const { label, labelY, imageY, alphaX } = placements[index];
277	+    cx.fillStyle = '#fff';
278	+    cx.fillText(
279	+      `${label} (${layer.width}×${layer.height}) · alpha`,
280	+      2,
281	+      labelY + 2
282	+    );
283	+    const { colors, alpha } = splitAlpha(layer.pixels);
284	+    cx.putImageData(
285	+      new ImageData(colors, layer.width, layer.height),
286	+      0,
287	+      imageY
288	+    );
289	+    cx.putImageData(
290	+      new ImageData(alpha, layer.width, layer.height),
291	+      alphaX,
292	+      imageY
293	+    );
294	+  });
295	+  return canvas;
296	+}
297	+
298	+/**
299	+ * Saves the layers as one PNG, `bacteria-gl-layers-<time>.png`, through the
300	+ * browser's download - on a phone too, which has no dev tools to read them
301	+ * with.
302	+ */
303	+export function downloadLayerSheet(layers: readonly CapturedLayer[]): void {
304	+  const canvas = layers.length === 0 ? null : drawSheet(layers);
305	+  canvas?.toBlob((blob) => {
306	+    if (blob == null) {
307	+      return;
308	+    }
309	+    const url = URL.createObjectURL(blob);
310	+    const link = document.createElement('a');
311	+    link.href = url;
312	+    link.download = `bacteria-gl-layers-${new Date().toISOString().replace(/[:.]/g, '-')}.png`;
313	+    link.click();
314	+    // A phone may still be fetching it when the click returns.
315	+    setTimeout(() => URL.revokeObjectURL(url), REVOKE_AFTER_MS);
316	+  }, 'image/png');
317	+}
