  random: () => number,
  options: GpuSimulationOptions = {}
): GridWar {
  return gpuSimulation(this.gl, balance, random, options);
}

/** The timer of the HUD's breakdown, once asked for. */
private timer: GpuTimer | null | undefined;

public gpuTimer(): GpuTimer | null {
  this.timer ??= GpuTimer.create(this.gl);
  return this.timer;
}

/** The GPU and driver this painter's context renders with. */
public renderer(): string {
  return rendererOf(this.gl);
}

public diagnose(): PainterDiagnostics {
  const diagnostics = diagnose(this.gl);
  return {
    renderer: this.renderer(),
    errors: () => diagnostics.errors(),
    captureLayers: () => this.captureLayers(),
  };
}

/**
 * Hands the context back to the browser right away rather than once the
 * canvas is collected - a page may only hold a few WebGL contexts.
 */
public dispose(): void {
  this.disposed = true;
  this.resources = null;
  this.timer?.dispose();
  this.gl.getExtension('WEBGL_lose_context')?.loseContext();
}

public setRenderScale(scale: number): void {
  const width = Math.max(1, Math.round(this.canvasWidth * scale));
  const height = Math.max(1, Math.round(this.canvasHeight * scale));
  if (width === this.renderWidth && height === this.renderHeight) {
    return;
  }
  const from = { width: this.renderWidth, height: this.renderHeight };
  this.renderWidth = width;
  this.renderHeight = height;
  const resources = this.resources;
  // Without a context, the restored one builds it at that size.
  if (resources == null) {
    return;
  }
  // The last frame goes along, scaled: the trail goes on from it, and a
  // snapshot before the next frame shows it rather than black.
  const gl = this.gl;
  const old = resources.trail;
  const trail = this.target(width, height, gl.LINEAR);
  gl.disable(gl.SCISSOR_TEST);
  gl.bindFramebuffer(gl.READ_FRAMEBUFFER, old.framebuffer);
  gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, trail.framebuffer);
  gl.blitFramebuffer(
    0,
    0,
    from.width,
    from.height,
    0,
    0,
    width,
    height,
    gl.COLOR_BUFFER_BIT,
    gl.LINEAR
  );
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  gl.deleteFramebuffer(old.framebuffer);
  gl.deleteTexture(old.texture);
  resources.trail = trail;
}

